-- LK Transportes — schema inicial de produção (PostgreSQL).
-- Gerado a partir das entidades JPA; a partir daqui, toda mudança de
-- modelo entra como uma migração nova (V2__..., V3__...), nunca editando esta.

create table avisos (fixado boolean not null, expira_em timestamp(6), publicado_em timestamp(6) not null, autor_id uuid, id uuid not null, tipo varchar(20) not null check (tipo in ('INFORMATIVO','ALERTA','EVENTO')), mensagem varchar(2000) not null, titulo varchar(255) not null, primary key (id));
create table caixa (percentual_comissao_padrao numeric(5,2) not null, saldo numeric(16,2) not null, id uuid not null, primary key (id));
create table caminhoes (dono_id uuid, id uuid not null, identificacao_interna varchar(255), marca varchar(255) not null, modelo varchar(255), placa varchar(255) not null unique, status varchar(255) not null check (status in ('ATIVO','MANUTENCAO')), primary key (id));
create table carretas (ativa boolean not null, id uuid not null, identificacao_interna varchar(255), placa varchar(255) not null unique, tipo varchar(255) not null, primary key (id));
create table cidades_mapa (vezes_vista integer not null, vista_em timestamp(6) not null, id uuid not null, id_jogo varchar(80) not null unique, nome varchar(80), primary key (id));
create table cnhs (pontos integer not null, primeira_habilitacao date, validade date not null, emitida_em timestamp(6) not null, categoria varchar(10) not null, emitida_por_id uuid, id uuid not null, motorista_id uuid not null unique, numero_registro varchar(20) not null, situacao varchar(20) not null check (situacao in ('ATIVA','SUSPENSA')), observacoes varchar(400), primary key (id));
create table compras (quantidade integer not null, valor_total numeric(14,2) not null, valor_unitario numeric(14,2) not null, criado_em timestamp(6) not null, id uuid not null, item_id uuid, motorista_id uuid not null, nome_item varchar(120) not null, primary key (id));
create table demanda_caminhoes (caminhao_id uuid not null, demanda_id uuid not null, primary key (caminhao_id, demanda_id));
create table demanda_reboques (demanda_id uuid not null, tipo varchar(40));
create table demandas (frete_por_tonelada numeric(12,2) not null, numero integer not null unique, prazo_entrega date, quantidade_entregue_kg numeric(14,3) not null, quantidade_total_kg numeric(14,3) not null, valor_carga_por_tonelada numeric(12,2), concluida_em timestamp(6), criada_em timestamp(6) not null, id uuid not null, status varchar(20) not null check (status in ('ABERTA','CONCLUIDA','CANCELADA')), observacoes varchar(600), carga varchar(255) not null, destino varchar(255) not null, empresa_destinataria varchar(255) not null, empresa_remetente varchar(255) not null, origem varchar(255) not null, primary key (id));
create table documentos_viagem (numero integer not null, snap_peso_kg numeric(12,3) not null, snap_valor_carga numeric(14,2), snap_valor_frete numeric(14,2), gerado_em timestamp(6) not null, serie varchar(10) not null, tipo varchar(10) not null check (tipo in ('NF','CTE','MDFE')), id uuid not null, viagem_id uuid not null, chave_interna varchar(60) not null unique, snap_caminhao varchar(255) not null, snap_carga varchar(255) not null, snap_carreta varchar(255), snap_destinatario varchar(255) not null, snap_destino varchar(255) not null, snap_motorista varchar(255) not null, snap_origem varchar(255) not null, snap_placa_caminhao varchar(255) not null, snap_placa_carreta varchar(255), snap_remetente varchar(255) not null, primary key (id));
create table empresas_parceiras (ativa boolean not null, estado varchar(2) not null, id uuid not null, cnpj_ficticio varchar(20), cidade varchar(255) not null, nome varchar(255) not null, segmento varchar(255), primary key (id));
create table eventos_viagem (litros numeric(10,3), valor numeric(14,2), valor_litro numeric(10,3), ocorrido_em timestamp(6) not null, registrado_em timestamp(6) not null, origem varchar(12) check (origem in ('MANUAL','TELEMETRIA')), caminhao_id uuid, id uuid not null, oficina_id uuid, posto_id uuid, viagem_id uuid not null, tipo varchar(20) not null, motivo varchar(500), observacao varchar(1000), servico varchar(1000), descricao varchar(2000), assinatura_base64 text, evidencia_url varchar(255), local_multa varchar(255), local_pedagio varchar(255), titulo varchar(255), primary key (id));
create table itens_loja (ativo boolean not null, estoque integer, preco numeric(14,2) not null, criado_em timestamp(6) not null, id uuid not null, categoria varchar(60), nome varchar(120) not null, descricao varchar(600), imagem_base64 text, primary key (id));
create table mapa_conhecido (margem_metros float(53) not null, maxx float(53), maxz float(53), minx float(53), minz float(53), id uuid not null, modo varchar(20) not null check (modo in ('APRENDENDO','ATIVO')), primary key (id));
create table movimentos_caixa (positivo boolean not null, saldo_depois numeric(16,2) not null, valor numeric(16,2) not null, criado_em timestamp(6) not null, id uuid not null, pagamento_id uuid, registrado_por_id uuid, viagem_id uuid, tipo varchar(20) not null check (tipo in ('FRETE','COMISSAO','AJUSTE')), descricao varchar(300) not null, primary key (id));
create table movimentos_carteira (positivo boolean not null, saldo_depois numeric(14,2) not null, valor numeric(14,2) not null, criado_em timestamp(6) not null, id uuid not null, motorista_id uuid not null, tipo varchar(20) not null check (tipo in ('ACERTO','COMPRA','AJUSTE')), descricao varchar(300) not null, primary key (id));
create table oficinas (ativa boolean not null, estado varchar(2) not null, id uuid not null, cidade varchar(255) not null, nome varchar(255) not null, primary key (id));
create table pagamentos (base_despesas numeric(14,2) not null, base_frete numeric(14,2) not null, numero integer not null unique, percentual_aplicado numeric(5,2) not null, valor numeric(14,2) not null, criado_em timestamp(6) not null, criado_por_id uuid, id uuid not null, motorista_id uuid not null, observacao varchar(400), primary key (id));
create table perfis (data_nascimento date, estado varchar(2), naturalidade_uf varchar(2), uf_emissor varchar(2), cep varchar(12), id uuid not null, usuario_id uuid not null unique, cpf varchar(20), rg varchar(20), orgao_emissor varchar(30), telefone varchar(30), apelido varchar(60), discord varchar(60), cidade varchar(80), naturalidade_cidade varchar(80), steam_id varchar(80), endereco varchar(120), nome_completo varchar(120), nome_mae varchar(120), nome_pai varchar(120), sobre varchar(600), assinatura_base64 text, foto_base64 text, primary key (id));
create table postos (ativo boolean not null, estado varchar(2) not null, id uuid not null, cidade varchar(255) not null, nome varchar(255) not null, primary key (id));
create table telemetria_sessao (carga_massa_kg float(53), combustivel_capacidadel float(53), combustivell float(53), dano_cabine_pct float(53), dano_cambio_pct float(53), dano_carga_pct float(53), dano_chassi_pct float(53), dano_motor_pct float(53), dano_rodas_pct float(53), distancia_planejada_km integer, em_servico boolean, marcha integer, odometro_km float(53), pausado boolean, piloto_automatico boolean, posx float(53), posy float(53), posz float(53), rpm float(53), velocidade_kmh float(53), atualizado_em timestamp(6) not null, id uuid not null, motorista_id uuid not null unique, carga_nome varchar(80), cidade_destino varchar(80), cidade_origem varchar(80), empresa_destino varchar(80), empresa_origem varchar(80), modelo_caminhao varchar(80), placa_caminhao varchar(80), primary key (id));
create table telemetria_viagem (abastecendo boolean, combustivel_ao_iniciar_abastecimento float(53), combustivel_atuall float(53), combustivel_iniciall float(53), dano_atual_pct float(53), dano_inicial_pct float(53), dano_registrado_pct float(53), distancia_confirmada_km float(53), fora_da_area boolean, litros_abastecidos float(53), odometro_atual_km float(53), odometro_inicial_km float(53), peso_jogo_kg float(53), saltos integer, usou_estacionamento_automatico boolean, usou_piloto_automatico boolean, id uuid not null, viagem_id uuid not null unique, carga_jogo varchar(80), cidade_destino_id varchar(80), cidade_origem_id varchar(80), divergencias varchar(500), primary key (id));
create table usuarios (percentual_comissao numeric(5,2), saldo_carteira numeric(14,2) not null, id uuid not null, token_telemetria varchar(64) unique, email varchar(255) not null unique, nome varchar(255) not null, papel varchar(255) not null check (papel in ('MOTORISTA','GESTOR')), senha_hash varchar(255) not null, status_acesso varchar(255) not null check (status_acesso in ('PENDENTE','APROVADO','BLOQUEADO')), primary key (id));
create table viagens (houve_avaria boolean, numero integer not null unique, peso_kg numeric(12,3) not null, valor_carga numeric(14,2), valor_frete numeric(14,2), criada_em timestamp(6) not null, finalizada_em timestamp(6), iniciada_em timestamp(6), liberada_em timestamp(6), caminhao_id uuid not null, carreta_id uuid, demanda_id uuid, id uuid not null, liberada_por_id uuid, motorista_id uuid not null, pagamento_id uuid, conferencia varchar(20) check (conferencia in ('APROVADA','RETIDA','LIBERADA')), status varchar(20) not null check (status in ('CRIADA','EM_ANDAMENTO','CONCLUIDA')), observacao_liberacao varchar(600), motivos_conferencia varchar(1000), observacao_final varchar(1000), carga varchar(255) not null, destino varchar(255) not null, empresa_destinatoria varchar(255) not null, empresa_remetente varchar(255) not null, origem varchar(255) not null, primary key (id));
